# region: sift
def sift(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: render
def render(xs, offset=1):
    return [v + offset for v in xs]

# region: emit
def emit(xs, factor=2):
    return [v * factor for v in xs]

# region: gather
def gather(xs, factor=2):
    return [v * factor for v in xs]

# region: intake
def intake(xs):
    n = len(xs) - 1
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: shape
def shape(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return shape(intake(gather(emit(render(sift(raw))))))

