import unittest
from program import run

class T(unittest.TestCase):
    def test_case_00(self):
        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'mean': 8.0, 'max': 8, 'ratio': 1.0})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 4, 'mean': 9.0, 'max': 12, 'ratio': 1.333})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 3, 'mean': 9.333333333333334, 'max': 12, 'ratio': 1.0})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 3, 'mean': 16.0, 'max': 16, 'ratio': 1.0})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'mean': 10.666666666666666, 'max': 12, 'ratio': 1.0})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'mean': 8.0, 'max': 8, 'ratio': 0.333})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'mean': 8.0, 'max': 8, 'ratio': 1.333})
    def test_case_07(self):
        self.assertEqual(run(['2', 'hello', '40']), {'n': 3, 'mean': 14.666666666666666, 'max': 24, 'ratio': 1.0})

